var membershipEvent=function(n){function t(){n("#membership-event").on("submit",function(t){t.preventDefault();var i=n("#luckyNumber").val();if(i==""&&i<0)return!1;n.ajax({method:"POST",url:"/membership-event/create",data:{luckyNumber:i},success:function(t){t.isSuccessful?(n("#Notice .modal-body").html("Bạn đã chọn số may mắn thành công"),n("#Notice").bind("hidden.bs.modal",function(){location.reload()})):(n("#Notice .modal-body").html(t.message),n("#Notice").unbind("hidden.bs.modal"));n("#Notice").modal("show")}})})}function i(){t()}return{init:i}}(jQuery);$(document).ready(function(){membershipEvent.init()});